function say(t){if(!voiceOn||!window.speechSynthesis)return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ru-RU';u.rate=.85;speechSynthesis.speak(u)}catch(e){}}
function sparks(n=9){for(let i=0;i<n;i++){const e=document.createElement('div');e.className='sp';e.textContent=['✨','⭐','💛','💜'][i%4];e.style.left=(10+Math.random()*78)+'vw';e.style.top=(30+Math.random()*35)+'vh';document.body.appendChild(e);setTimeout(()=>e.remove(),1300)}}
const $=s=>document.querySelector(s),app=$('#app'),shuf=a=>[...a].sort(()=>Math.random()-.5);
const clr=()=>{clearInterval(IV);TM.forEach(clearTimeout);TM=[]};
const learned=()=>L.filter(l=>S.d[l.i]),canPlay=()=>learned().length>=3;
const unlocked=i=>S.open||i==0||S.d[i-1];
const bar=()=>`<div class="bar"><button class="ib" data-a="hub">🏠</button><span class="pill">⭐ ${S.st} · ${learned().length}/28</span><span><button class="ib" data-a="voice">${voiceOn?'🔊':'🔇'}</button> <button class="ib" data-a="info">ℹ️</button></span></div>`;
function target(){const ll=learned(),rec=ll.slice(-4);return (Math.random()<.6?rec:ll)[Math.floor(Math.random()*(Math.random()<.6?rec.length:ll.length))]||ll[0]}
function others(t,k){return shuf(learned().filter(l=>l.i!=t.i&&l.nm!=t.nm)).slice(0,k)}
function hub(){clr();const nx=L.findIndex(l=>!S.d[l.i]),all=nx<0;
 let secs='';for(let u=0;u<7;u++){secs+=`<div class="sec">Уровень ${u+1}</div><div class="g4">`+L.slice(u*4,u*4+4).map(l=>`<button class="tile ${unlocked(l.i)?'':'lock'}" style="--lc:${COL[l.i].n}" data-a="learn" data-i="${l.i}">${LET[l.i]}<b>${l.nm} ${S.d[l.i]?'✅':''}</b></button>`).join('')+'</div>'}
 app.innerHTML=bar()+`<section class="welcome-card">
  <div class="welcome-copy">
    <span class="welcome-kicker">✦ ПЕРВОЕ ПРИКЛЮЧЕНИЕ</span>
    <h1 class="ar">الحروف العربية</h1>
    <h2>Арабские буквы</h2>
    <p class="welcome-text">Знакомься с буквами, учись узнавать их форму и собирай звёзды вместе с нашим зайчиком.</p>
    <button class="btn g" data-a="learn" data-i="${all?0:nx}"><span class="ar">${nx==0?'ابدأ تعلم الحروف العربية':all?'راجع من البداية':'تابع التعلم'}</span><small>${nx==0?'Начать учить арабские буквы':all?'Повторить с начала':'Продолжить'}</small></button>
  </div>
  <div class="welcome-mascot"><img src="./assets/mascot.svg" alt="Зайчик-помощник в изучении арабских букв"></div>
</section><h3>Игры</h3><div class="games">${GM.map(g=>`<button class="gm ${canPlay()?'':'lock'}" data-a="${g.k}"><i>${g.ic}</i><span>${g.t}<br><small style="font-weight:600">${canPlay()?'Нажми, чтобы играть':'Выучи сначала 3 буквы'}</small></span></button>`).join('')}</div><h3>Буквы</h3>${secs}`}
function lines(l){const dots=l.dots?l.dots+'.':'Точек у неё нет.';
 return [`Привет! Давай познакомимся с ${l.ord} арабской буквой!`,`Это буква ${l.nm} (${l.ar}). Она похожа на ${l.shape}. ${dots}`,`Посмотри: слово «${l.tr}» — ${l.ru} — начинается с этой буквы!`,l.hard?'Этот звук трудный: такого нет в русском языке. Попроси взрослого включить запись носителя языка!':`Звук буквы — «${l.sn}». Послушай и скажи вместе со мной!`,`Пишем эту букву ${l.i==0?'сверху вниз ↓':'справа налево ←'}. Теперь обведём её!`]}
function learn(i){clr();cur=i;const l=L[i],c=COL[i],ln=lines(l);
 app.innerHTML=bar()+`<div class="bb" id="bb">…</div><div class="stg" style="--lc:${c.n};--lt:${c.tint}"><div class="lc" id="lc"><div class="dir">${l.dir}</div>${LET[i]}</div><div class="wp" id="wp"><div class="ph">${ILL[i]}</div><div class="aw ar"><span style="color:var(--lc)">${[...l.wd][0]}</span>${[...l.wd].slice(1).join('')}</div><small>${l.tr} — ${l.ru}</small></div></div><div class="row" id="ct"></div>`;
 const bb=$('#bb'),lc=$('#lc'),at=(ms,f)=>TM.push(setTimeout(f,ms));
 ln.forEach((t,k)=>at(700+k*4600,()=>{bb.textContent=t;say(t);if(k==0){lc.classList.add('on');win()}if(k==2){$('#wp').classList.add('on');sparks(6)}if(k==3){lc.classList.add('snd');at(1600,()=>lc.classList.remove('snd'))}if(k==4)lc.classList.add('dirOn')}));
 at(700+ln.length*4600-800,()=>{$('#ct').innerHTML='<button class="btn w" data-a="again">🔁 Ещё раз</button><button class="btn g" data-a="paint">✏️ Обвести букву ▶</button>'})}
function paint(){clr();const l=L[cur],g=GL[cur],cl=COL[cur];
 app.innerHTML=bar()+`<div class="bb" id="bb">Обведи букву пальцем!</div><div class="card" style="padding:12px"><canvas id="cv" width="360" height="330"></canvas><div class="prog" style="margin:10px 0"><i id="pg"></i></div><div class="row"><button class="btn w" data-a="done">Пропустить ▶</button><button class="btn g" id="nx" style="display:none" data-a="done">Готово ▶</button></div></div>`;
 say('Обведи букву пальцем!');
 const mk=()=>{const x=document.createElement('canvas');x.width=360;x.height=330;return x},A=mk(),M=mk(),B=mk(),T=mk(),gA=A.getContext('2d'),gM=M.getContext('2d'),gB=B.getContext('2d'),gT=T.getContext('2d'),cv=$('#cv'),c=cv.getContext('2d');
 const sc=Math.min(250/g.h,320/g.w),ox=(360-g.w*sc)/2,oy=(330-g.h*sc)/2,P=new Path2D(g.all);
 const shape=(q,p,col,lw)=>{q.save();q.translate(ox,oy);q.scale(sc,sc);q.lineJoin='round';q.lineWidth=lw/sc;q.fillStyle=q.strokeStyle=col;q.fill(p);q.stroke(p);q.restore()};
 shape(gA,P,'#8a74d6',34);shape(gA,P,'#f4f0ff',22);g.dots.forEach(d=>shape(gA,new Path2D(d),'#ffe9a0',22));shape(gM,P,'#fff',22);
 const m=gM.getImageData(0,0,360,330).data,mask=new Uint8Array(360*330);let tot=0,cnt=0,fin=0,last=null,dr=0;const pt_=new Uint8Array(360*330);
 for(let i=0;i<mask.length;i++)if(m[i*4+3]>128){mask[i]=1;tot++}
 const draw=()=>{c.clearRect(0,0,360,330);c.drawImage(A,0,0);gT.globalCompositeOperation='source-over';gT.clearRect(0,0,360,330);gT.drawImage(B,0,0);gT.globalCompositeOperation='destination-in';gT.drawImage(M,0,0);c.drawImage(T,0,0)};draw();
 const xy=e=>{const r=cv.getBoundingClientRect();return[(e.clientX-r.left)*360/r.width,(e.clientY-r.top)*330/r.height]};
 const dab=(x,y)=>{const R=16;for(let dy=-R;dy<=R;dy++)for(let dx=-R;dx<=R;dx++){if(dx*dx+dy*dy>R*R)continue;const X=Math.round(x+dx),Y=Math.round(y+dy);if(X<0||Y<0||X>=360||Y>=330)continue;const i=Y*360+X;if(mask[i]&&!pt_[i]){pt_[i]=1;cnt++}}};
 const go=e=>{const[x,y]=xy(e);gB.lineCap=gB.lineJoin='round';gB.lineWidth=34;gB.strokeStyle=cl.n;gB.beginPath();gB.moveTo(last?last[0]:x,last?last[1]:y);gB.lineTo(x+.01,y);gB.stroke();
  const[lx,ly]=last||[x,y],n=Math.max(1,Math.ceil(Math.hypot(x-lx,y-ly)/5));for(let k=0;k<=n;k++)dab(lx+(x-lx)*k/n,ly+(y-ly)*k/n);last=[x,y];draw();
  const p=Math.min(1,cnt/tot/.62);$('#pg').style.width=p*100+'%';if(!fin&&p>=1){fin=1;win();sparks(12);say('Молодец!');$('#nx').style.display='inline-block'}};
 cv.addEventListener('pointerdown',e=>{dr=1;last=null;cv.setPointerCapture(e.pointerId);go(e)});cv.addEventListener('pointermove',e=>{if(dr)go(e)});cv.addEventListener('pointerup',()=>{dr=0;last=null})}
function done(){clr();const l=L[cur];if(!S.d[l.i]){S.d[l.i]=1;S.st+=2;save()}const nx=L[cur+1],unitEnd=cur%4==3;
 app.innerHTML=bar()+`<div class="card"><h2>Ты выучил(а) букву «${l.nm}»!${unitEnd?' Уровень пройден! 🎉':''}</h2><div style="width:230px;margin:0 auto">${LET[cur]}</div><div class="row" style="margin-top:10px">${nx?`<button class="btn g" data-a="learn" data-i="${cur+1}">Следующая буква ▶</button>`:''}${canPlay()?'<button class="btn w" data-a="hub">К играм 🎮</button>':'<button class="btn w" data-a="hub">Меню</button>'}</div></div>`;win();sparks(14);say(unitEnd?'Молодец! Уровень пройден!':'Молодец!')}
function fin(){clr();S.st+=3;save();app.innerHTML=bar()+`<div class="card"><h2>Победа! +3 ⭐</h2><div class="row">${shuf(learned()).slice(0,3).map(l=>`<div style="width:30%">${LET[l.i]}</div>`).join('')}</div><button class="btn g" data-a="hub">Ещё игра</button></div>`;win();sparks(16);say('Победа!')}
function drag(el,fn){let s=null;el.onpointerdown=e=>{el.setPointerCapture(e.pointerId);s={x:e.clientX,y:e.clientY};el.classList.add('dr');pop()};
 el.onpointermove=e=>{if(s)el.style.transform=`translate(${e.clientX-s.x}px,${e.clientY-s.y}px) scale(1.15) rotate(${(e.clientX-s.x)/25}deg)`};
 el.onpointerup=e=>{if(!s)return;s=null;el.classList.remove('dr');const r=fn(e.clientX,e.clientY);if(r=='eat'){el.style.pointerEvents='none';el.style.opacity=0;el.style.transform='scale(.2)'}else el.style.transform=''}}
const hintOf=l=>`Ищи ${l.shape} ${l.hd}.`;
function g1(){clr();let n=0,T=8,t,bx=.5,items=[],last=performance.now();
 app.innerHTML=bar()+`<div class="card" style="padding:12px"><h2 id="tg"></h2><div id="fl" class="fld"><div id="bk">${NET}</div></div></div>`;
 const fl=$('#fl'),bk=$('#bk'),nt=()=>{t=target();$('#tg').innerHTML=`Поймай букву «${t.nm}» · ${n}/${T}`;say('Поймай букву '+t.nm)};nt();
 fl.onpointermove=fl.onpointerdown=e=>{const r=fl.getBoundingClientRect();bx=Math.max(.1,Math.min(.9,(e.clientX-r.left)/r.width))};
 IV=setInterval(()=>{const l=Math.random()<.5?t:shuf(others(t,3)).concat(t)[0],el=document.createElement('div');el.className='fi';el.innerHTML=LET[l.i];fl.appendChild(el);items.push({el,id:l.i,x:.14+Math.random()*.72,y:-90,v:85+Math.random()*55})},1350);
 const frame=now=>{if(!document.body.contains(fl))return;const dt=Math.min(.05,(now-last)/1000);last=now;const r=fl.getBoundingClientRect(),W=r.width,H=r.height;bk.style.left=bx*W+'px';
  items.forEach(it=>{it.y+=it.v*dt;it.el.style.transform=`translate(${it.x*W-43}px,${it.y}px)`;
   if(!it.dead&&it.y>H-190&&it.y<H-115&&Math.abs(it.x-bx)*W<66){it.dead=1;it.el.remove();if(it.id==t.i){pop();win();sparks(5);n++;if(n>=T)fin();else nt()}else{bad();bk.classList.add('sh');setTimeout(()=>bk.classList.remove('sh'),400)}}else if(it.y>H)it.el.remove()});
  items=items.filter(i=>i.el.isConnected);requestAnimationFrame(frame)};requestAnimationFrame(frame)}
function g2(){clr();let r=0,T=6,t,miss=0;
 const q=()=>{if(r>=T)return fin();t=target();miss=0;const o=shuf([t,...others(t,2)]);
  app.innerHTML=bar()+`<div class="card"><div class="bb" id="bb" style="min-height:60px">Почта просит букву «${t.nm}»! · ${r}/${T}</div><div class="mail" id="mn">${MAIL}</div><p>Перетащи письмо с буквой в почтовый ящик 📮</p><div class="row" style="gap:6px;margin-top:4px">${o.map(x=>`<div class="drg" data-i="${x.i}">${LET[x.i]}</div>`).join('')}</div></div>`;say('Почта просит букву '+t.nm);
  document.querySelectorAll('.drg').forEach(d=>drag(d,(x,y)=>{const m=$('#mn').getBoundingClientRect();if(Math.hypot(x-(m.left+m.width/2),y-(m.top+m.height*.45))>m.width*.5)return false;
   if(+d.dataset.i==t.i){$('#mn').classList.add('yes');win();sparks(8);say('Письмо отправлено! Ура!');r++;setTimeout(q,1700);return 'eat'}
   $('#mn').classList.add('no');bad();$('#bb').textContent='Подсказка: '+hintOf(t);say(hintOf(t));setTimeout(()=>$('#mn')&&$('#mn').classList.remove('no'),400);if(++miss>=2)document.querySelector(`.drg[data-i="${t.i}"]`).style.filter='drop-shadow(0 0 12px #fff)';return false}))};q()}
function g3(){clr();let r=0,T=6,t,miss=0;
 const q=()=>{if(r>=T)return fin();t=target();miss=0;const hs=shuf([t,...others(t,2)]);
  app.innerHTML=bar()+`<div class="card"><div class="bb" id="bb" style="min-height:60px">Отнеси букву к её слову · ${r}/${T}</div><div class="row" style="min-height:190px"><div class="drg" id="dg" style="width:46%;max-width:170px">${LET[t.i]}</div></div><div class="hs">${hs.map(x=>`<div class="hse" data-i="${x.i}" style="--lc:${COL[x.i].n};--lt:${COL[x.i].tint}"><div class="rf"></div><div class="wl"><div style="width:74px">${ILL[x.i]}</div></div></div>`).join('')}</div></div>`;say('Куда отнести эту букву? К её слову!');
  drag($('#dg'),(x,y)=>{for(const h of document.querySelectorAll('.hse')){const b=h.getBoundingClientRect();if(x>b.left&&x<b.right&&y>b.top-30&&y<b.bottom){if(+h.dataset.i==t.i){win();sparks(8);say('Да! '+t.nm+' — '+t.ru);r++;setTimeout(q,1500);return 'eat'}bad();$('#bb').textContent='Подсказка: '+hintOf(t);say(hintOf(t));if(++miss>=2)document.querySelector(`.hse[data-i="${t.i}"]`).classList.add('hint');return false}}return false})};q()}
function info(){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="card"><h2>Родителям</h2><p>28 арабских букв в порядке алфавита. Буква всегда остаётся чистой, точки выделены жёлтым, у каждой буквы свой цвет.</p><p>🔊 Голос — голос устройства: он может неточно произносить арабские звуки. Для трудных звуков лучше записи носителя языка.</p><p>Названия букв, слова и их русская транскрипция требуют проверки преподавателем арабского: источники расходятся.</p><div class="row"><button class="btn w" data-a="openall">${S.open?'Закрыть порядок':'Открыть все буквы'}</button><button class="btn w" data-a="reset">Сбросить прогресс</button><button class="btn g" data-a="close">Закрыть</button></div></div>`;document.body.appendChild(m)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(!b)return;const a=b.dataset.a;
 if(a=='learn'){if(unlocked(+b.dataset.i))learn(+b.dataset.i)}else if(a=='again')learn(cur);else if(a=='hub')hub();else if(a=='paint')paint();else if(a=='done')done();else if(a=='g1')g1();else if(a=='g2')g2();else if(a=='g3')g3();else if(a=='voice'){voiceOn=!voiceOn;b.textContent=voiceOn?'🔊':'🔇'}
 else if(a=='info')info();else if(a=='close')b.closest('.modal').remove();else if(a=='openall'){S.open=S.open?0:1;save();b.closest('.modal').remove();hub()}else if(a=='reset'){S={d:{},st:0,open:0};save();b.closest('.modal').remove();hub()}});
hub();
